parameters.jsCode:
// Score against the ICP
// Deterministic ICP score from firmographics and role, plus intent points for the source page, message content and repeat visits. Thresholds are in a sheet sales ops owns.
return $input.all();

parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "summary": { "type": "string" },
    "draft": { "type": "string", "description": "The message or document text this step produced, ready to send or review" },
    "subject": { "type": "string" },
    "confidence": { "type": "number" },
    "needs_human": { "type": "boolean" },
    "reasons": { "type": "array", "items": { "type": "string" } }
  },
  "required": ["summary", "confidence", "needs_human"]
}
